  "settings.configurations.note": "Вся ваша настройка в одном файле — для нового компьютера, перед перестройкой или для возврата в заведомо исправное состояние. Раньше они находились в разделе <em>Радио → Ограничения передачи и совместное использование</em>, где их никто не нашел.",
