  "settings.workspace.looks.touch": "Нажмите",
  "settings.workspace.looks.custom": "Пользовательский",
  "settings.workspace.looks.custom.title": "Ваше собственное сочетание этих настроек. Он не соответствует ни одному из образов, и нажатие на один из них заменяет его.",
  "settings.workspace.looks.undo": "Отменить",
  "settings.workspace.looks.undo.title": "Верните настройки, которые у вас были до этого образа.",
  "settings.workspace.looks.hint": "Хижина, Поле/POTA и Ночь настраивают весь экран. Режимы «Конкурс», «Большой и четкий» и «Сенсорный» задают размер текста, плотность и контрастность, сохраняя режим «Поле» и «Ночной» такими, какие они есть. Функция No Look меняет вашу тему, масштаб пользовательского интерфейса, цвета, водопадные палитры или настройку «Ночь» на «Авто».",
  "settings.workspace.language.label": "Язык",
  "settings.workspace.language.hint": "Записывается на языке Nexus. Частоты, отчеты о сигналах, позывные, квадраты сетки, названия диапазонов и режимов никогда не переводятся и не переформатируются — циферблат читается одинаково на всех языках.",
  "settings.workspace.theme.label": "Тема",
  "settings.workspace.theme.hint": "Свет лучше всего читается на открытом воздухе при дневном свете; Чип Field на верхней панели повышает контрастность и размер в любой теме, которую вы используете.",
  "settings.workspace.contrast.label": "Высокая контрастность",
  "settings.workspace.contrast.on": "Вкл.",
  "settings.workspace.contrast.off": "Выкл.",
  "settings.workspace.contrast.hint": "Более четкое выделение текста на фоне в любой теме, которую вы используете, и в том размере, который у вас уже есть. Включите это, если экран плохо читается — масштаб пользовательского интерфейса не изменится.",
  "settings.workspace.contrast.hint.field": "Режим поля включен, поэтому высокая контрастность уже применена. Эту настройку вы всегда выбираете сами, и она сохраняется на экране, когда вы выключаете полевой режим.",
  "settings.workspace.night.label": "Ночь",
  "settings.workspace.night.off": "Выкл.",
  "settings.workspace.night.on": "Вкл.",
  "settings.workspace.night.auto": "Авто",
  "settings.workspace.night.hint": "Более темный и теплый экран для работы в темное время суток, какую бы тему вы ни использовали. Красный цвет передачи, цвета предупреждений и сигналов остаются прежними.",
  "settings.workspace.night.hint.auto": "Включается в сумерках и гаснет на рассвете в вашем квадрате сетки: когда солнце находится там 6° ниже горизонта.",
  "settings.workspace.night.hint.noGrid": "Автоматическому режиму нужен квадрат сетки (Настройки ▸ Станция ▸ Сетка), чтобы знать, когда садится солнце. Пока он не появится, Ночь остается в стороне.",
  "settings.workspace.field.label": "Полевой режим",
  "settings.workspace.field.on": "Вкл.",
  "settings.workspace.field.off": "Выкл.",
  "settings.workspace.field.hint": "Максимальная контрастность и более крупный шрифт в одном переключателе — для дневного света на открытом воздухе и для любого экрана, на котором трудно читать. Тот же элемент управления, что и у чипа Field в верхней панели.",
  "settings.workspace.scale.label": "Масштаб пользовательского интерфейса",
  "settings.workspace.scale.mode.aria": "Режим масштабирования пользовательского интерфейса",
  "settings.workspace.scale.auto": "Авто (подходит)",
  "settings.workspace.scale.manual": "Руководство",
  "settings.workspace.scale.aria": "Масштаб пользовательского интерфейса",
  "settings.workspace.scale.cap.label": "Максимальный масштаб (автоматически не превысит)",
  "settings.workspace.scale.cap.aria": "Максимальный масштаб пользовательского интерфейса",
  "settings.workspace.scale.cap.unreachable": "Это окно вмещается только до {{fits}}% — окно или монитор большего размера разблокирует {{wanted}}%.",
  "settings.workspace.scale.auto.hint.tooSmall": "Вмещает весь интерфейс в окно, поэтому ничего не обрезается (на данный момент {{scale}}%). Максимальное значение этого окна составляет {{fits}}% — повышение ограничения не поможет, пока вы не увеличите окно или не переключитесь в ручной режим, чтобы увеличить масштаб.",
  "settings.workspace.scale.auto.hint.limited": "Вмещает весь интерфейс в окно, поэтому ничего не обрезается (на данный момент {{scale}}%). Это окно умещается до {{fits}}%; для больших кепок требуется большее окно или монитор. Водопад остается острым.",
  "settings.workspace.scale.auto.hint.full": "Вмещает весь интерфейс в окно, поэтому ничего не обрезается (на данный момент {{scale}}%). Водопад остается острым. Поднимите максимум для больших мониторов.",
  "settings.workspace.scale.manual.hint": "Фиксированный масштаб. Переключитесь на «Авто», чтобы автоматически подогнать интерфейс под окно.",
