  "shell.lane.audio.message": "РАДИО ОСТАНОВЛЕНО",
  "shell.lane.scopeSpan.message": "ОБЪЕМ ОБЪЕМА ОТКАЗАН",
  "shell.lane.radioConfig.message": "КОНФИГ РАДИО",
  "shell.lane.txPowerZero.message": "НЕТ RF ПИТАНИЯ",
  "shell.lane.txPowerZero.detail": "Радиостанция сообщает о мощности 0% и передача включена — она включается и ничего не передает в эфир. Проверьте ползунок Pwr и собственную мощность установки для ЭТОГО режима: установки Yaesu сохраняют отдельный уровень для SSB, DATA, CW и AM.",
  "shell.lane.recording.message": "ЗАПИСЬ",
  "shell.lane.parsecStop.message": "PARSEC УДАЛЕНО — TX ОСТАНОВЛЕНО",
  "shell.lane.parsecStop.detail": "Ваш сеанс Parsec прервался (или журнал Parsec перестал отвечать) на {{time}} UTC, поэтому Nexus остановился: {{what}}. Ничего не было перезапущено; включите ключ еще раз, когда вернетесь.",
  "shell.lane.parsecStop.what.ptt": "зафиксировано PTT",
  "shell.lane.parsecStop.what.rtty": "непрерывный RTTY",
  "shell.lane.parsecStop.what.psk": "непрерывный PSK",
  "shell.lane.parsecStop.what.tune": "Tune",
  "shell.lane.slotKeyRefused.message": "PTT ОТКАЗАН — TX ОСТАНОВЛЕН",
  "shell.lane.slotKeyRefused.detail": "Радио не принимало PTT на {{time}} UTC ({{why}}), поэтому over не отправлялось и TX отключалось. Проверьте метод PTT и CAT/порт, затем снова включите TX.",
  "shell.lane.slotKeyRefused.flex.notYetDax": "Nexus не переключил {{mode}} на {{time}} UTC: встроенный звук Flex DAX включен, но радиостанция еще не принимала передаваемый звук от Nexus через DAX. Ничего не было отправлено, и TX был отключен. Nexus мгновенно завершает настройку радио; затем снова включите TX.",
  "shell.lane.slotKeyRefused.flex.daxUnfed": "Nexus не переключил {{mode}} на {{time}} UTC: встроенный звук Flex DAX отключен, но радиостанция все еще принимала передаваемый звук от DAX, как это установил Nexus, и теперь ничего не передает DAX. Ничего не было отправлено, и TX был отключен. Nexus мгновенно возвращает радио на микрофонный вход; затем снова включите TX.",
  "shell.lane.slotUnkeyFailed.message": "PTT ВЫКЛ. ОШИБКА — TX ОСТАНОВЛЕНО",
  "shell.lane.slotUnkeyFailed.detail": "Радио не приняло выключение PTT в {{time}} UTC ({{why}}), поэтому TX было выключено. Возможно, передача все еще ведется: проверьте радио сейчас. Nexus продолжает отправлять PTT до тех пор, пока радиостанция не примет его. Включите TX снова, как только радио начнет принимать сигнал.",
  "shell.lane.slotAudioLost.message": "ЗАКОНЧЕНО — TX ОСТАНОВЛЕНО",
  "shell.lane.slotAudioLost.detail": "Собственный звук Flex DAX выключился в момент {{time}} UTC в середине овера, так что остальная часть этого овера пропала бы. Nexus закончил там и выключил TX. Включите TX еще раз, чтобы продолжить.",
  "shell.lane.pttRefused.message": "PTT ОТКАЗАН",
  "shell.lane.pttRefused.detail": "Nexus не переключил {{mode}} на {{time}} UTC: радиостанция по-прежнему получала передаваемый звук от DAX, как установил Nexus, а не от микрофона, поэтому ваш голос не пропал бы. Ничего не было отправлено. Отпустите PTT и Nexus мгновенно вернет радио на микрофонный вход; затем снова нажмите PTT.",
  "shell.lane.clockRepairHold.message": "РЕМОНТ ЧАСОВ — TX ПРОДОЛЖЕН",
  "shell.lane.clockRepairHold.detail": "Nexus ремонтирует часы этого компьютера. Ничего не начнет передаваться до тех пор, пока не закончится ремонт, самое большее две минуты, чтобы часы не могли двигаться в середине овера.",
  "shell.lane.prop.offline.message": "Реквизит: нет живых данных",
  "shell.lane.prop.offline.detail": "Данных о реальном распространении пока нет — установите свой позывной в настройках и проверьте подключение к Интернету.",
  "shell.lane.prop.cached.message": "Опора: кэшировано {{minutes}}m",
  "shell.lane.prop.cached.detail": "Не удалось выполнить обновление в реальном времени — показан последний удачный снимок.",
