  "shell.logStore.network": "Nexus не открыл базу данных журнала, поскольку ваша папка с данными находится на сетевом диске, где база данных может быть повреждена из-за способа блокировки файлов в сети. Ничего не потеряно: в этом сеансе ваш логин сохраняется в log.adi, как и раньше. Чтобы использовать базу данных, переместите папку данных на диск внутри этого компьютера в «Настройки» ▸ «Конфигурация» ▸ «Папка данных и журналов».",
  "shell.logStore.failed": "Nexus не удалось открыть базу данных журнала. Причина: {{reason}}. Ничего не потеряно: в этом сеансе ваш логин сохраняется в log.adi, как и раньше. Подробная информация содержится в журнале диагностики: «Настройки» ▸ «Журнал и соединители» ▸ «Интеграции и каналы» ▸ «Журнал диагностики».",
  "shell.keptFile.pendingQso": "Nexus не удалось прочитать файл QSOs, ожидавший в поле «Записать это QSO?» всплывающее окно, поэтому он сохранил этот файл нетронутым в {{path}}. Ничего не было удалено.",
  "shell.keptFile.fieldDay": "Nexus не смог прочитать всю резервную копию вашего Field Day или журнала соревнований, поэтому он сохранил этот файл нетронутым в {{path}} и начал новое резервное копирование из контактов, которые он мог прочитать. Ничего не было удалено.",
  "shell.keptFile.js8Inbox": "Nexus не смог прочитать ваш почтовый ящик JS8, поэтому оставил этот файл нетронутым в {{path}} и открыл новый почтовый ящик. Ничего не было удалено.",
  "shell.keptFile.pendingMsgs": "Nexus не смог прочитать файл с сообщениями Tempo, ожидающими отправки, поэтому сохранил этот файл нетронутым в {{path}}. Ничего не было удалено.",
  "shell.keptFile.assistance": "Nexus не смог прочитать вашу запись Assistance, поэтому он оставил этот файл нетронутым в {{path}} и начал новую запись. Ничего не было удалено.",
  "shell.keptFile.conversations": "Nexus не смог прочитать ваши разговоры с Tempo, поэтому он сохранил этот файл нетронутым в {{path}} и начал без него. Ничего не было удалено.",
  "shell.keptFile.settings": "Nexus не смог прочитать ваши настройки, поэтому сохранил этот файл нетронутым в {{path}} и запустил его с настройками по умолчанию. Ничего не было удалено.",
  "shell.keptFile.other": "Nexus не смог прочитать один из своих файлов, поэтому он оставил этот файл нетронутым в {{path}} и запустил новый. Ничего не было удалено.",
  "shell.keptFile.keptInPlace": "Nexus не смог прочитать {{path}} и не смог переместить его в сторону, поэтому он оставил файл там, где он есть, и не будет записывать поверх него. Ничего не было удалено. Переместите или восстановите файл, затем перезапустите Nexus.",
  "shell.keptFile.settingsKeptInPlace": "Nexus не смог прочитать ваши настройки в {{path}} и не смог переместить этот файл в сторону, поэтому он запустился с настройками по умолчанию и не сохранит никаких настроек в этом файле. Ничего не было удалено. Переместите или восстановите файл, затем перезапустите Nexus.",
  "quit.logbook.saving.title": "Сохранение журнала…",
