  "topbar.tier.ft2.title": "FT2 — режим быстрого слотирования Decodium (3.75 с), FT4 с уменьшенным вдвое временем символа. Передавать и получать. Нет настроек: период фиксированный",
  "topbar.tier.wspr.title": "Радиомаяки распространения WSPR — с интервалом 2 минуты. Передача по расписанию; установите процент передачи и мощность в «Настройки» ▸ «Маяки» (WSPR и FST4W)",
  "topbar.tier.q65.title": "Q65 — EME / VHF+ разброс. Передавать и получать. Точка + подрежим в Настройках ▸ Q65",
  "topbar.tier.msk144.title": "MSK144 — meteor scatter. Transmits for nearly the whole period (that is how the mode works). Period in Settings ▸ MSK144",
  "topbar.tier.jt65.title": "JT65 — classic EME, 60 s. Receive only in this build (transmit is disabled pending a fix). Submode in Settings ▸ JT65",
  "topbar.tier.fst4.title": "FST4 — slow weak-signal QSO mode (LF/MF). Transmit and receive",
  "topbar.tier.fst4w.title": "FST4W — LF/MF beacons. Transmits on a schedule; set the transmit % and power in Settings ▸ Beacons (WSPR & FST4W). Hashed calls show as <...>",
