  "topbar.holdTx.label": "Hold Tx",
  "topbar.holdTx.title": "Hold Tx Freq: keep your TX offset where you put it when you double-click a station to work them. Off, your TX moves onto theirs (WSJT-X's behaviour). A plain waterfall click never moves TX either way.",
  "topbar.slotClock.title": "Time to next slot",
