  "topbar.clock.corrected.label": "clock {{offset}} ✓",
  "topbar.clock.corrected.title": "Your PC clock is {{offset}} off UTC and Nexus is already correcting for it — transmit and decode windows land on the true UTC grid. Measured {{age}} ago, {{servers}} time servers agreeing.",
  "topbar.clock.logNote": "Logged QSO times still come from the PC clock, so this one is worth fixing at the machine.",
  "topbar.clock.stale.label": "clock unchecked",
  "topbar.clock.stale.title": "The last UTC measurement was {{age}} ago and has aged out, so Nexus has stopped correcting — slot timing now follows the PC clock directly. It resumes on its own as soon as a time server answers.",
  "topbar.clock.gross.label": "clock {{offset}} ✗",
  "topbar.clock.gross.title": "Your PC clock is {{offset}} off UTC — too far for Nexus to correct, and your logged QSO times would be wrong by the same amount. Set the clock on the machine itself (off-grid: GPS).",
  "topbar.clock.repair.label": "Repair clock",
