  "topbar.clock.repair.note": "asks for admin rights",
  "topbar.clock.repair.title": "Fix what the clock check found. Windows asks for administrator rights first, and Nexus runs the fix only when you press this.",
  "topbar.clock.repair.onAir": "Not while transmitting: a clock repair can move the clock in the middle of an over. Try again when the transmitter is idle.",
  "topbar.clock.repair.midMessage": "Not in the middle of a message: a JS8 or Tempo message is still going out, and a clock repair would pause it between two of its overs. Try again when it has finished.",
  "topbar.clock.repair.running": "A clock repair is already running. Answer the Windows prompt, or wait for it to finish.",
