  "setup.rig.flexNote.other": "{{radio}} на {{ip}} — модель и радиоадрес сохранены. SmartSDR CAT только для Windows: поместите адрес Windows-ПК, на котором оно работает (slice A = его порт 5002), в поле Сетевой адрес ниже, затем проверьте CAT.",
