  "setup.rig.second.swap": "Обе радиостанции используют одинаковые звуковые карты USB, каждая выделена по одной. Если позже вы заметите, что приборы <em>неправильной</em> установки показывают движение при воспроизведении аудио, <a>поменяйте их местами</a>.",
  "setup.rig.second.twoWindows": "Чтобы запустить оба радио одновременно, откройте Nexus дважды — каждое окно управляет одним радио (лаунчер спрашивает, какое).",
  "setup.log.title": "Принесите ваш существующий журнал",
  "setup.log.sub": "Nexus работает лучше всего, когда знает вашу историю. Импорт вашего журнала ADIF — это то, что обеспечивает работу флагов <b>worked-before</b>, доски <b>Needed</b> (новые DXCC / состояния / сетки) и прогресса ваших <b>awards</b> — без этого приложение начинает «слепым» и воспринимает каждую станцию как новую. Это необязательно, и вы можете импортировать в любое время из Журнала, но это самое важное, что делает приложение полезным с первого дня.",
  "setup.log.import.action": "Импортировать мой журнал ADIF…",
  "setup.log.import.again": "Импортировать другой файл ADIF",
  "setup.log.import.busy": "Импортируется…",
  "setup.log.import.failed": "Импорт не удался: {{error}}",
  "setup.log.result.imported": { "one": "✓ Импортировано <b>{{count}}</b> QSO{{dupes}}. Ваша ранее использованная и необходимая доска теперь установлены.", "other": "✓ Импортировано <b>{{count}}</b> QSOs{{dupes}}. Ваша ранее использованная и необходимая доска теперь установлены." },
  "setup.log.result.dupes": "{{count}} уже присутствует",
  "setup.log.result.allDupes": "✓ Все {{count}} QSOs уже были в вашем журнале — вы засеяны.",
  "setup.log.result.none": "⚠ В этом файле не найден QSOs — это стандартный экспорт ADIF (.adi/.adif)?",
  "setup.log.sources": "Из WSJT-X, N1MM, Log4OM, HRD, QRZ, LoTW, ClubLog — любой стандартный экспорт ADIF (.adi/.adif). Ничего не покидает ваш компьютер; дубликаты обнаруживаются и пропускаются.",
  "setup.finish.title": "Ты получаешь всё",
  "setup.finish.sub": "Каждый режим и каждый раздел начинается ВКЛ — FT8/FT4, Телефон, CW, RTTY, SSTV, APRS, спутники, карты, всё полностью. Nexus — это одна программа вместо шести; ничего не нужно разблокировать. Если когда-либо захочется более простой приложение, убирайте разделы в Настройках.",
  "setup.finish.license.title": "Какая у тебя лицензия?",
  "setup.finish.license.sub": "Устанавливает ваши привилегии передачи — приложение ставит набор в сегменты вашего лицензированного диапазона и не позволит передавать за их пределами. Выберите «За пределами США» для отсутствия ограничений.",
  "setup.finish.license.technician": "Техник",
  "setup.finish.license.technician.blurb": "США — ограниченный HF + полный VHF/UHF",
  "setup.finish.license.general": "Общий",
  "setup.finish.license.general.blurb": "США — большинство HF привилегий",
  "setup.finish.license.extra": "Любитель Экстра",
  "setup.finish.license.extra.blurb": "США — полные привилегии",
  "setup.finish.license.open": "За пределами США",
  "setup.finish.license.open.blurb": "Нет ограничений на передачу",
  "setup.finish.packs.title": "Начать с нескольких каналов?",
  "setup.finish.packs.sub": "Необязательно — готовый набор распространённых частот и сетей, добавленных в ваши Памяти. Позже вы можете изменить или удалить любые из них в разделе Памяти.",
  "setup.finish.packs.meta": "{{count}} каналов · {{region}}",
  "setup.finish.guide.title": "Хотите пройтись по тому, что вы только что настроили?",
