  "profiles.starter.label": "Только начинаю",
  "profiles.starter.blurb": "Установите несколько контактов FT8/FT4. Чистая кабина и простой журнал — лишнее пусть остаётся вне зоны.",
  "profiles.dx.label": "DX погоня и награды",
  "profiles.dx.blurb": "Преследуйте новые: награды (DXCC/Вызов/Доска почета/WAZ), распространение, карта и доска DXpedition.",
  "profiles.contest.label": "Оспаривание",
  "profiles.contest.blurb": "Скорость выполнения: рабочее пространство конкурса и журнал поля, с наградами и реквизитом, убранными с дороги.",
  "profiles.pota.blurb": "Активируйте и охотьтесь: карта и полевой журнал для работы парков и вершин.",
  "profiles.vhf.label": "6m / VHF & вакансии",
  "profiles.vhf.blurb": "Поймайте процесс оживления группы: условия (карта + открытые позиции), пролёты спутников и плата DXpedition.",
  "profiles.everything.label": "Всё (эксперт)",
  "profiles.everything.blurb": "Включите всю консоль. Все разделы и функции активированы.",
  "assist.state.unassisted": "БЕЗ ПОМОЩИ",
  "assist.state.assisted": "ССЫЛОЧНЫЙ",
  "assist.sources.off": "Источники помощи отключены: декодер ИИ CW, кластер DX / RBN, потребности PSK Reporter.",
  "assist.sources.offSince": "Источники помощи отключены с {{since}}: декодер ИИ CW, кластер DX / RBN, потребности PSK Reporter.",
  "assist.sources.on": "Декодер ИИ CW, кластер DX / RBN и PSK Reporter нужды обеспечивают идентификацию позывного.",
  "assist.sources.onSince": "Декодер ИИ CW, кластер DX / RBN и PSK Reporter обеспечивают идентификацию позывного с {{since}}.",
  "assist.toggle.declare": "Заявить о самостоятельном въезде",
  "assist.toggle.end": "Завершить самостоятельный вход",
  "assist.why.summary": "Что это означает для вашей категории конкурса",
  "assist.why.cqww": "Правило VIII.2 <b>CQ WW</b> считает «CW декодер, DX кластер, веб-сайты спотов DX … локальные или удаленные технологии декодирования позывных и частот (например, CW Skimmer или Reverse Beacon Network)» помощью в поиске QSO. Использование любого из них переводит заявку в <b>Single Operator Assisted</b> (V.A.2) вместо Single Operator (V.A.1).",
  "assist.why.arrl": "<b>ARRL</b> соревнования называют это помощью в обнаружении и называют «PSKReporter, Telnet, DX сайты для обнаружения или доски объявлений, автоматизированные многоканальные декодеры». Single Operator не может её использовать (HCAT.1.1: «Использование помощи в обнаружении не разрешено.»). <b>Single Operator Unlimited</b> могут (HCAT.2.1). Глоссарий ARRL определяет многоканальный декодер как программное обеспечение, которое «отображает несколько декодированных сигналов одновременно». Nexus декодирует один сигнал за раз, поэтому это определение не описывает его CW декодер. Оно описывает кластер, RBN и PSK Reporter потоки.",
  "assist.why.ownDecodes": "Ваши <b> собственные декодеры радио </b> не являются помощью ни по одному из правил, поэтому они продолжают питать Необходимую доску в автономном режиме. Ваши исходящие PSK Reporter загрузки также продолжают работать, потому что ARRL говорит: «Генерация информации о споттинге для использования другими станциями не считается споттинг-помощью.»",
  "assist.why.notCovered": "<b>Что этот переключатель не охватывает:</b> POTA и SOTA точки активации всё ещё появляются. Ни одно из правил не называет эти источники, но оба достаточно широко определяют помощь, чтобы включать их, поэтому отключите функции POTA/SOTA вручную, если вы участвуете в конкурсе, где они учитываются.",
  "assist.why.checkRules": "Правила различаются в зависимости от конкурса и меняются из года в год, поэтому <b>проверьте правила конкурса, в котором вы участвуете</b>. В этой заметке сообщается то, что CQ WW и ARRL в настоящее время публикуют. Это не постановление по категории.",
  "assist.keep": "Ваши собственные настройки никогда не переписываются. Завершение режима без помощи восстанавливает декодер и передает точно так, как вы их настроили.",
  "callbook.lookupFailed": "не удалось выполнить поиск QRZ",
