  "logbook.parkStates.button": "Проверьте состояния парка",
  "logbook.parkStates.buttonTitle": "Перечислите контакты парка и вершины, у которых штат не совпадает с парком, и исправьте те, которые вы отметили",
  "logbook.parkStates.title": "Проверьте состояния парка",
  "logbook.parkStates.intro": "Эти контакты парка и вершины находятся в другом штате, кроме того, в котором находится их парк или вершина, или не имеют штата: Nexus использовался для того, чтобы записывать штат проживания активатора, исходя из его лицензии или записи в справочнике вызовов. Отметьте те, которые нужно изменить. Ничего не изменится, пока вы не нажмёте кнопку, и ничего не загружается повторно. Подтверждённый контакт изначально не отмечен.",
  "logbook.parkStates.reading": "Читаю ваш журнал…",
