  "logbook.parkStates.confirmedTitle": "Подтверждено: его подтверждение пришло вместе с документом, который подписала другая станция. Отметьте это только если вы уверены.",
  "logbook.parkStates.cancel": "Отмена",
  "logbook.parkStates.apply": { "one": "Изменить контакт {{count}}", "other": "Изменить контакты {{count}}" },
