  "logbook.confirmations.done.uploads": { "one": "Отмечен контакт {{count}} как не загруженный в LoTW.", "other": "Отмечено {{count}} контактов как не загруженные в LoTW." },
  "logbook.confirmations.done.gained": { "one": "{{count}} контакт получил подтверждение того, что {{service}} для него действует.", "other": "Контакты {{count}} получили подтверждение, которое {{service}} держит для них." },
  "logbook.confirmations.done.skipped": { "one": "Отмеченная строка {{count}} была оставлена без изменений: её контакт изменился после проверки.", "other": "Линии с {{count}} галочками оставили без изменений: их контакты изменились после проверки." },
  "logbook.confirmations.done.beforeFile": "Изменённые контакты, как они были, находятся в {{path}}. Журнал ▸ Импорт ADIF возвращает их на место.",
