  "logbook.export.lacks.held": { "one": "{{count}} изменение журнала отказов не включено в экспорт. Nexus сохраняет это в памяти на этой сессии и спрашивает об этом при выходе.", "other": "{{count}} изменяет, что журнальные записи, которые были отклонены, не включены в экспорт. Nexus хранит их в памяти на эту сессию и спрашивает о них при выходе." },
  "logbook.export.activation.label": "активация",
