  "logbook.lotw.upload.timeless": { "one": "— Импортированный {{count}} QSO не имеет времени суток и никогда не может совпасть с LoTW, поэтому они не отправляются", "other": "— {{count}} импортированные [QSOs не имеют времени суток и никогда не могут совпадать с LoTW, поэтому они не отправляются" },
