  "logbook.lotw.skipped.edited": { "one": "{{count}} был отредактирован и предлагается снова при следующей загрузке.", "other": "{{count}} были отредактированы и предлагаются снова с следующей загрузкой." },
  "logbook.lotw.skipped.deleted": { "one": "{{count}} был удалён из журнала.", "other": "{{count}} были удалены из журнала." },
  "logbook.markLotw.label": "Отметить на LoTW",
  "logbook.markLotw.title": "Уже есть эти на LoTW (загружены через другой инструмент)? Отметьте их, чтобы Nexus перестал считать их нуждающимися в загрузке.",
  "logbook.markLotw.aria": "Отметить как уже на LoTW",
  "logbook.markLotw.heading": { "one": "Пометить {{formatted}} QSO как уже на LoTW?", "other": "Пометить {{formatted}} QSOs как уже на LoTW?" },
  "logbook.markLotw.body": { "one": "Используйте это, если вы импортировали лог, который уже загрузили другим способом на LoTW (Ham2K Polo, TQSL…). Это помечает {{formatted}} незагруженные QSO как уже находящиеся на LoTW, поэтому счетчик <b>Загрузить на LoTW</b> прекращает предлагать их повторно отправлять. Обновляется только собственная запись Nexus — ничего не отправляется, и ваш аккаунт и лог LoTW остаются нетронутыми. Новые QSOs, которые вы создадите позже, все равно загружаются как обычно.", "other": "Используйте это, если вы импортировали лог, который уже загрузили другим способом на LoTW (Ham2K Polo, TQSL…). Это помечает {{formatted}} незагруженные QSOs как уже находящиеся на LoTW, поэтому счетчик <b> «Загрузить на LoTW</b>» перестает предлагать повторную отправку. Обновляется только собственная запись Nexus — ничего не отправляется, и ваш LoTW аккаунт и лог не затрагиваются. Новые QSOs, которые вы создадите позже, все равно загружаются обычным образом." },
  "logbook.markLotw.cancel": "Отмена",
  "logbook.markLotw.confirm": "Отметьте {{formatted}} как на LoTW",
  "logbook.markLotw.failed": "Не удалось обновить состояние LoTW",
  "logbook.markLotw.done": { "one": "Отмечено {{formatted}} QSO как уже на LoTW", "other": "Отмечено {{formatted}} QSOs как уже на LoTW" },
  "logbook.markLotw.nothing": "Нечего отмечать",
  "logbook.purge.label": "Журнал очистки",
  "logbook.purge.title": "Удалите все контакты в локальной записной книжке (необратимо)",
  "logbook.purge.aria": "Очистить журнал",
  "logbook.purge.heading": "Очистить весь журнал?",
  "logbook.purge.irreversible": "Необратимый",
  "logbook.purge.warn": { "one": "Это навсегда удаляет <b>все {{count}} контакты</b> из вашего локального журнала и переписывает ADIF файл, делая его пустым. Это <b>не</b> удаляет ничего из того, что вы уже загрузили в LoTW, QRZ, eQSL или ClubLog. Отменить это невозможно — сначала экспортируйте ADIF резервную копию, если вы можете захотеть её сохранить.", "other": "Это навсегда удаляет <b>все {{count}}контакты</b> из вашего локального журнала и переписывает ADIF файл пустым. Оно <b>не</b> удаляет ничего, что вы уже загрузили на LoTW, QRZ, eQSL или ClubLog. Это действие нельзя отменить — сначала экспортируйте ADIF резервную копию, если вы можете захотеть её сохранить." },
  "logbook.purge.syncWarn": "Это также сбрасывает ваше <b>LoTW и eQSL положение синхронизации</b>, так что следующая синхронизация повторно загружает всю вашу историю подтверждений вместо только недавних совпадений. Именно это возвращает ваши подтверждения после очистки — но это занимает значительно больше времени, чем обычная синхронизация, поэтому дайте процессу время завершиться.",
