  "recall.contestDupe.titleLogged": "Уже в журнале конкурса на {{band}} — всё равно выполняйте и записывайте: этот конкурс сохраняет дубликаты и оценивает их нулём. Пропуск приведёт к потере других станций их заслуг.",
  "recall.contestDupe.titleAnyBand": "Уже в журнале конкурса — этот конкурс учитывает станцию один раз независимо от диапазона, поэтому повторная запись будет отклонена как дубликат.",
  "recall.contestDupe.titleLoggedAnyBand": "Уже в журнале конкурса — этот конкурс учитывает станцию только один раз независимо от диапазона. Всё равно работайте и записывайте: дубликаты сохраняются и оцениваются нулём. Исключение станции лишает другую станцию её зачёта.",
