  "operate.dxped.hound.title": "DXpedition гончая: вызовы идут выше 1000 Hz, ваш R+отчет автоматически перемещается на частоту Fox, и QSO заканчивается на Fox RR73 без прощального 73 — 73 там QRM в собственном сегменте Fox. Нажмите, чтобы включить и выключить; уже запущенный QSO сохраняет правила, с которыми он был запущен. Снова выключено при каждом запуске: включайте для DXpedition, а не на день.",
  "operate.dxped.superfox.note": "SuperFox в эфире: {{calls}} — Nexus не декодирует SuperFox в этой версии. Пророботайте это в WSJT-X.",
  "operate.dxped.superfox.title": "A SuperFox DXpedition передаёт в формате, для которого у этой версии Nexus нет декодера, поэтому его передачи не попадают в список декодирования здесь, и Hound не может помочь. Обработайте это в WSJT-X и зафиксируйте обратно в Nexus.",
  "operate.header.source.aria": "Источник сигнала",
