  "waterfall.flow.down.title.dss": "Прокручивая вниз — новая строка появляется сверху, а история движется вниз. Нажмите, чтобы изменить порядок: новые — внизу, история движетcя вверх (по умолчанию). 3D-вид сохраняет свою собственную перспективу спереди назад в любом случае.",
