  "waterfall.flow.up.title.dss": "Прокрутка вверх — новая строка появляется вНИЗУ, а история движется вверх (по умолчанию). Нажмите, чтобы изменить: новые записи вверху, история движется вниз. 3D-вид сохраняет свою перспективу спереди назад в любом случае.",
