  "scope.canvas.keys.aria": "Область действия: ← и → настраивают, с Shift — большими шагами; Enter вводит частоты на сигнал в полосе пропускания; [ и ] сужают и расширяют фильтр; ↑ и ↓ прокручивают назад во время паузы",
