  "scope.rows.sweep.label": "Ряд за проход",
  "scope.rows.smooth.title": "Плавная прокрутка — водопад двигается равномерно. Когда развертка радио отображается медленнее этого, самая последняя развертка повторяется до прихода следующей, и каждый повтор записывается как один. Щелкните, чтобы получить одну строку на каждую развертку.",
  "scope.rows.sweep.title": "Одна строка на каждый проход — водопад движется только тогда, когда радио посылает новый проход, поэтому медленный осциллограф прокручивается медленно, ступенчато, и каждая строка новая. Нажмите для плавной прокрутки.",
