  "meters.tx.swr.unverified": "Согласование антенны — это собственная необработанная цифра радиоприёмника, и у Nexus нет проверенной шкалы для этой модели, поэтому он не может сказать, что здесь считается высоким. Следите за тем, в какую сторону она движется при настройке; абсолютное число может быть сильно неверным, и ничто не мешает вашей передаче при этом.",
