  "settings.integrations.clusterNodes.addCustom.action": "+ Пользовательский",
  "settings.integrations.clusterNodes.hint": "Мы подключаемся ко ВСЕМ перечисленным узлам и объединяем их человеческие SSB/телефонные точки — больше узлов = шире покрытие телефонов (RBN CW + цифровое соединение автоматически; RBN конечные точки здесь игнорируются). Nexus никогда не изменяет этот список за вас. Добавленный узел подключается, а удалённый — отключается при следующем сохранении.",
  "settings.integrations.clusterNodes.mode.auto": "Автоматически выбирать рабочие узлы (рекомендуется)",
  "settings.integrations.clusterNodes.mode.manual": "Используй мой список",
  "settings.integrations.clusterNodes.autoHint": "Nexus поддерживает два таких узла для SSB/телефонных точек и распределяет по ним операторов. Узел, который перестает отвечать на пять минут, пока работают другие ваши потоки, пропускается на день, и его место занимает другой. Тихая полоса никогда не учитывается против узла. RBN CW + цифровое подключение автоматически в любом случае. Вступает в силу при следующем сохранении.",
