  "settings.integrations.clusterNodes.preset": "{{callsign}} — {{software}}, порт {{port}}",
  "settings.integrations.clusterSsid.label": "Вход в кластер SSID",
  "settings.integrations.clusterSsid.hint": "Добавлено к вашему позывному при входе (2 = W9XYZ-2). Узел разрешает одну сессию на позывной и отключает более старую, поэтому второй Nexus — или другая программа кластера на том же позывном — отключит эту сессию, если каждый не использует другой SSID. 1-99, или оставьте пустым, чтобы войти с вашим обычным позывным. Ваши споты все равно будут попадать в сеть под вашим обычным позывным. На узле, который требует регистрации, зарегистрируйте также позывной с суффиксом, иначе он не позволит публиковать споты. Вступает в силу после следующего сохранения.",
