  "settings.integrations.propEngine.hint": "Управляет прогнозом пути для каждой станции + сеткой 24 часа × полоса. P.533 — это реальный метод надежности цепи (проверенный по эталону ITU; ~0.1 с на предсказание, использует мощность вашей станции). Живые точки всегда выигрывают у любой модели.",
