  "settings.mapGlobe.legend": "Карта и глобус",
  "settings.mapGlobe.note": "Вид карты условий (глобус, плоская или луч), её слои и цвета выбираются непосредственно на карте, а Conditions сохраняет отдельный набор для каждой деятельности, которую вы выбираете там.",
  "settings.performance.legend": "Производительность",
