  "settings.performance.motion.system": "Следуйте за компьютером",
  "settings.performance.motion.reduce": "Уменьшить",
  "settings.performance.motion.hint": "Уменьшение отключает анимации и эффекты затухания, что также помогает медленному компьютеру справляться. Уведомления по-прежнему отображаются; они просто перестают пульсировать. Следуйте настройке компьютера для уменьшения движения, используя собственные настройки вашей системы.",
  "settings.dataFolder.legend": "Папка данных и журналов",
  "settings.dataFolder.note": "Ваш журнал, таблицы данных Nexus загрузки и почтовый ящик Winlink находятся в одной папке. Держите её на диске внутри этого компьютера. Nexus хранит ваш журнал в базе данных, а база данных на сетевом диске может быть повреждена из-за работы блокировки файлов в сети, поэтому сетевой диск не допускается. Синхронизированная папка (Dropbox, OneDrive, iCloud, Google Drive) разрешена, но только ОДИН Nexus может использовать её одновременно: два компьютера, записывающие один журнал через клиент синхронизации, создают конфликтную копию, а не объединённый журнал.",
  "settings.dataFolder.onNetwork": "Эта папка находится на сетевом диске. Nexus хранит ваш журнал в базе данных, и база данных на сетевом хранилище может быть повреждена из-за того, как работает блокировка файлов по сети — в худшем случае журнал не откроется. Скопируйте папку на диск внутри этого компьютера и укажите Nexus на копию.",
  "settings.dataFolder.onSync": "Похоже, что эта папка синхронизируется с помощью Dropbox, OneDrive, iCloud или Google Drive. Только ОДИН Nexus может использовать её одновременно — два компьютера, записывающие в один журнал через клиент синхронизации, создадут конфликтную копию, а не объединённый журнал.",
  "settings.dataFolder.current.label": "Папка используется",
  "settings.dataFolder.source.env": "Установлено NEXUS_DATA_DIR для этого запуска, что побеждает эту настройку.",
  "settings.dataFolder.source.chosen": "Выбран здесь.",
  "settings.dataFolder.source.default": "Папка по умолчанию.",
  "settings.dataFolder.pending": "Выбрано: {{path}} — Nexus использует это в следующий раз, когда начнется.",
