  "roam.disclaimer": "<b>Не приватно — объявлено открыто.</b> Согласованные QSY действия вас и одной другой станции на новый канал вместе, с перемещением, отправленным в открытом виде (FCC Part 97 запрещает шифрование / скрытое значение, и ваш позывной идентифицируется каждые 10 минут). Это сбивает с толку <em>случайный</em> сканер, оставшийся на старой частоте — это <em>не</em> скрывает вас от кого-либо с широкополосным приемником, кто может следить. Используйте это для анти-QRM и умеренной скрытности, никогда не для секретности.",
