  "sat.rail.uplink.switch.label": "переключить отображение",
  "sat.rail.uplink.confirm.label": "подтвердить восходящую связь",
  "sat.rail.uplink.switch.title": "Переключите {{rig}} на {{pair}}. Ваше отображение не может пройти через этот радиопередатчик — ничего на него не записано — и это расположение Nexus дисков здесь. Ничего не меняется, пока вы не кликнете, а неверное отображение передается по вашему собственному каналу связи.",
  "sat.rail.uplink.confirm.title": "Подтвердите {{pair}} для {{rig}}. Nexus считайте это со своей радиомодели; ничего не поступает на ваш передатчик VFO до того, как вы это подтвердите, и неправильная привязка передает по вашей собственной линии связи.",
  "sat.rail.uplink.confirmMapping.title": "Подтвердите {{mapping}} — выбранное вами отображение — для {{rig}}. Ничто не достигает своего передатчика VFO до того, как вы подтвердите это для этого радиоприемника, а неверное отображение передается на вашу собственную нисходящую линию связи.",
  "sat.rail.vfoMap.aria": "Картирование спутником VFO",
  "sat.rail.vfoMap.title": "Какой VFO несет ваш аплинк — сопоставьте это с тем, как подключено ваше радио. Неправильное сопоставление передает сигнал на ваш собственный даунлинк, в полосу пропускания выхода спутника, поверх всех остальных, кто работает с спутником. Выбор одного подтверждает его для радио, которым управляет Doppler. Любое сопоставление, кроме «Аплинк», только поддерживает коррекцию даунлинка; «Аплинк» только передает ваш один VFO на передающую линию.",
  "sat.rail.elements.current": "{{age}} d старый — текущий",
