  "sat.binding.unpegged.title": "Фиксация штыря ВЫКЛЮЧЕНА — подбор направляется к радио, которое владеет диапазоном и классом режима. Нажмите, чтобы закрепить активное радио.",
  "sat.lockOn.name": "Набор",
  "sat.lockOn.state": "сдвинулись с транспондера? верни радио на самолет",
  "sat.lockOn.label": "Захватить цель",
  "sat.lockOn.title": "Повторно выполните выбор вашего транспондера — маршруты, устанавливает диапазон и режим, записывает оба звена и вновь центрирует вас в полосе пропускания. Используйте это после ручного перемещения диска с транспондера или когда аппаратура вернулась куда-то в другое место.",
  "sat.badge.rotorLost.title": "Ротатор перестал отвечать, так что этот трек отпустил его — направляйте антенну сами. Проходной час, транспондер и Doppler продолжают путь к LOS.",
  "sat.badge.passOnly.title": "Только прохождение по времени — ничего не приводится в движение: нет ротора на этом треке, и Doppler не управляет диском (коррекция выключена, транспондер не удерживается или используется только uplink-карта, которая не управляет этим прохождением). Часы прохождения и геометрия продолжают работать.",
  "sat.badge.dopplerOnly.title": "На этой трассе нет ротатора — Doppler {{what}}; антенну ничего не двигает",
