  "sat.sked.scanned": "{{grid}}, {{dist}} прочь · {{birds}} ★ птиц за {{days}} дней · окну нужно {{el}}° с ОБЕИХ сторон",
  "sat.sked.none": "Окна с {{grid}} не будет в течение следующих {{days}} дней. Для птицы на низкой орбите обе станции должны находиться внутри одного и того же покрытия в одно и то же время — после того, как они будут разделены примерно на {{dist}}, этого никогда не происходит, независимо от того, что говорит расписание.",
