  "sat.transponder.txMode.commanded": "Режим TX: восходящая (разделённая) VFO установлена на <b>{{tx}}</b> — нисходящая остаётся {{down}}, пока Doppler выполняет этот проход.",
  "sat.transponder.txMode.notCommanded": "Эта птица наклоняет {{up}} вверх / {{down}} вниз (SatNOGS) — режим TX не выполняется для этого прохода ({{why}}).",
  "sat.transponder.txMode.why.dopplerOff": "коррекция Doppler отключена",
