  "sat.transponder.txMode.why.shared": "ноги делят боковую полосу, или режим ваш",
  "sat.transponder.txMode.forecast": "TX боковая полоса: эта птица движется {{up}} вверх / {{down}} вниз (SatNOGS). Как только ваша карта восходящей связи подтверждена для используемого радио, TX (разделённый) VFO устанавливается соответствующим образом, пока выполняется отслеживаемый проход.",
  "sat.transponder.txMode.forecastCw": "Режим TX: эта птица передвигается {{up}} вверх / {{down}} вниз (SatNOGS). После того как ваша карта подключения подтверждена для используемого радиоприемника, отслеживаемый проход устанавливает TX (разделенный) VFO на CW, когда вы работаете с ним через телефон или с помощью собственного CW ключа радиоприемника; звуковая карта CW ключа получает режим передачи данных, который требуется для заданного тона.",
  "sat.transponder.state.dopplerOff": "Коррекция Doppler отключена, поэтому ничего не настраивается. Включите её в Настройки ▸ Радио ▸ Спутник Doppler.",
  "sat.transponder.state.uplinkOnly.driving": "Ваша карта только для исходящей связи сохраняет набор для звонка за вами — настроен только передающий VFO.",
  "sat.transponder.state.uplinkOnly.unconfirmed": "Ваша карта только для восходящей линии не подтверждена для этого радио — ничего не настраивается. Подтвердите это на проходной шине.",
  "sat.transponder.state.uplinkOnly.pending": "Ваша карта только для восходящей связи сохраняет набор за вами — передатчик VFO настраивается один раз, когда он подтвержден для используемого радио, и выполняется отслеживаемый проход.",
  "sat.transponder.state.tuning": "Doppler настраивает этот транспондер, пока автослежение отслеживает проход.",
  "sat.transponder.otherBird": "Doppler держит транспондер на {{name}}. Выбор одного здесь снимает его с устройства.",
