  "sat.credit.fetching": "передатчики для этой птицы ещё не получены — получение с SatNOGS DB при подключении к сети",
  "sat.passline.beyond": "следующий проход над вами поднимается {{time}} ({{countdown}})",
  "sat.passline.none": "в течение следующих 24 часов прохода над вами не будет",
  "sat.log.note": "Регистрирует контакт с вашего набора, точно так же, как панели журналов Phone и CW. На нисходящей линии спутника LoTW показывает список — тот, с которым вы работаете, или последний, с которым работали, пока не выберете другой — Nexus отмечает его за вас: он записывает поля ADIF, PROP_MODE и SAT_NAME, чтобы контакт учитывался для LoTW кредитов спутника <b> и собственных итогов спутника Nexus</b>. Всё остальное регистрируется как обычный контакт, и на 2 м его сетка учитывается для вашей земной VUCC, которую контакт через спутник не даёт. Чтобы отметить его самостоятельно, добавьте оба поля <b> и </b> — одно без другого при подписании отклоняется.",
  "sat.log.note.title": "Фиксирует контакт с вашего набора номера, точно так же, как панели журналов Phone и CW. На нисходящей линии спутника LoTW отображает списки — тот, с которым вы работаете, или последний, с которым вы работали, пока не выберете другой — Nexus отмечает его для вас: он записывает поля ADIF, PROP_MODE и SAT_NAME, так что контакт учитывается для LoTW спутникового кредита и для собственных спутниковых сумм Nexus. Всё остальное фиксируется как обычный контакт, а на 2 метрах его сетка учитывается для вашего наземного VUCC, что за спутниковый контакт не начисляется. Чтобы отметить контакт самостоятельно, добавьте ОБА поля — одно без другого при регистрации отклоняется.",
