  "program.coverageGap": "{{source}} здесь не указывает ни одного <b>{{band}}</b> репитера, что необычно для района, где они есть — его сельское покрытие непоследовательно, поэтому в этом списке, вероятно, недостаёт устройств. Добавление токена API RepeaterBook в <b>Настройки ▸ Интеграции</b> закрывает этот пробел.",
  "program.missingStates": "RepeaterBook не ответил за <b>{{states}}</b>, поэтому повторители там отсутствуют в этом списке. Это не пустая область, а неудачная попытка получить данные — попробуйте снова через несколько минут.",
