  "aprs.inet.gate.held.reason": "iGate включен: {{uploaded}} внесли вклад, {{held}} сдерживались (последнее: {{reason}}).",
  "aprs.radioNote.label": "на {{name}}",
  "aprs.radioNote.detail": "{{count}} ваших радиостанций охватывает этот диапазон, поэтому APRS пришлось сделать выбор. Следует за активной радиостанцией, в данный момент это {{name}} — если это не радиостанция, к которой подключён ваш пакетный звук, это объясняет, почему ничего не декодируется. Правила маршрутизации определяют, какая радиостанция получает данный диапазон: Настройки → Радиостанции.",
  "aprs.health.level.silence": "ввод за последние 0.1 с: цифровая тишина (ровно ноль)",
  "aprs.health.level.peak": "входной пик за последние 0.1 с: {{db}} дБФС",
  "aprs.health.dbfs.silence": "тишина",
  "aprs.health.norf.label": "Радио 2 м",
  "aprs.health.norf.detail": "Это радио не охватывает {{freq}} MHz, поэтому оно не может принимать RF APRS. RF APRS требуется VHF радио. Интернет-трансляция работает без него — включите её, чтобы видеть APRS движение, о котором сообщают другие станции.",
  "aprs.health.off.label": "Монитор выключен",
  "aprs.health.off.detail": "Декодер APRS не работает. Активируйте монитор, чтобы декодировать аудио RX.",
  "aprs.health.wrongFreq.label": "Неверная частота",
  "aprs.health.wrongMode.label": "Неправильный режим",
  "aprs.health.wrongMode.detail": "Радио включено в {{want}}, но в {{mode}} — APRS нужен FM. Пакетное аудио FM, демодулированное как SSB, искажено, поэтому ничего не будет декодироваться, независимо от силы сигнала. Настройтесь на канал APRS, чтобы начать его слышать.",
  "aprs.health.wrongFreqMode.detail": "Радио включено {{dial}} {{mode}} — APRS нуждается в {{want}} FM. Ничто на этом канале не может расшифровываться как APRS пакет, независимо от того, что говорит уровень аудио. Настройтесь на канал APRS, чтобы начать его слышать.",
  "aprs.health.wrongFreq.detail": "Радио включено {{dial}} — APRS нуждается в {{want}}. На этом канале ничего не может быть декодировано как пакет APRS, независимо от того, что показывает уровень звука. Настройтесь на канал APRS, чтобы начать его слышать.",
  "aprs.health.noCapture.label": "Нет ввода",
  "aprs.health.noCapture.detail": "Вооружено, но звуковые образцы вообще не поступают — устройство захвата ничего не передает. Убедитесь, что входное устройство (RX) в Настройки ▸ Радио ▸ Аудио — это радиоприемник (а не микрофон или отключенное устройство); то, что вы слышите в динамике, не говорит о том, что приложение захватывает.",
  "aprs.health.decoding.label": "{{count}} расшифровано",
  "aprs.health.decoding.detail": "Декодировано {{count}} пакетов с момента взведения. Вживую {{level}}.",
  "aprs.health.decoding.detail.aged": "Декодировано {{count}} пакетов с момента включения, последний {{age}} назад. В прямом эфире {{level}}.",
  "aprs.health.unreadable.label": "{{count}} не прошёл проверку CRC",
  "aprs.health.unreadable.detail": "{{count}} вспышек слышно с момента включения, последняя — {{age}} назад, ни одна не прошла проверку контрольной суммы. Часть этого нормальна: когда шумоподавитель открывается посреди вспышки, начало пакета теряется, и частично услышанный пакет никогда не пройдет проверку. Это считается неисправностью только если ничего никогда не декодируется — в этом случае проверьте, что установка включена на {{channel}} в FM.{{advice}} Последняя вспышка достигла пика {{burst}}; в эфире {{level}}.",
  "aprs.health.advice.clipping": "Перегрузка КЛИППИНГ (пиклован {{peak}}, {{samples}} выборка(ы) на рельсах) — снизьте уровень AF выхода установки USB или уровень входа Windows для этого устройства. Пакет выдерживает много клиппинга, так что это влияет на запас по громкости, а не на декодирование, но нет причин доходить до рельсов.",
  "aprs.health.advice.quiet": "Пик всплеска составил {{peak}}, что значительно ниже здорового диапазона {{min}}–{{max}} — увеличьте уровень выходного сигнала USB AF на установке (IC-9700: SET > Connectors > USB AF Output Level) или уровень входа Windows для этого устройства. Это дает запас против шума; само по себе это не причина сбоя контрольной суммы.",
  "aprs.health.silent.label": "Тихий",
  "aprs.health.silent.detail": "Вход активен и передает аудио, но он молчит — обычно это просто означает, что шумоподавление закрыто между пакетами, что и выглядит как бездействующий канал FM. Чтобы проверить маршрутизацию, откройте шумоподавление: здесь должен появиться шипящий звук в виде уровня. Если при открытом шумоподавлении все еще отображается молчание, выбран неправильный входной устройство. Активный {{level}}.",
  "aprs.health.listening.label": "Слушание",
  "aprs.health.listening.detail": "Аудио доходит до декодера, и недавно пакеты не были получены — тихий канал. В прямом эфире {{level}}. При открытом гейте шипение должно находиться примерно на уровне {{hiss}}; всплеск пакетов должен достигать пиков от {{min}} до {{max}}.",
