  "js8.seam.stationsInbox.label": "Станции / Входящие",
  "js8.waterfall.splitter.label": "высота водопада",
  "js8.panel.activity.title": "Каждый декодированный кадр на каждой включенной скорости — E/A/B/C это скорость (Медленно/Нормально/Быстро/Turbo), затем смещение, SNR и сообщение. Бледные строки — копия с низкой достоверностью; курсивные строки закрыты без их последнего кадра.",
  "js8.panel.activity.differs": "Один список, где JS8Call разделяет на два: это текущая расшифровка, в хронологическом порядке. Панель активности группы содержит те же декодировки, свернутые в одну строку на каждый смещение, с DT.",
  "js8.panel.activity.empty": "Прослушивание… кадры декодируются на каждой включенной скорости, вывод здесь",
  "js8.panel.activity.row.title": "Дважды щёлкните, чтобы написать на эту станцию",
  "js8.panel.offsets.title": "Одна строка на каждое смещение частоты в полосе пропускания — последнее декодирование, услышанное там, с его возрастом, SNR, DT (насколько отправитель отличается от слотового таймера) и скоростью. Читайте это, чтобы найти чистое смещение и увидеть, кто синхронизирован.",
  "js8.panel.offsets.empty": "Прослушивание… каждый сдвиг в полосе пропускания получает строку при декодировании",
  "js8.panel.offsets.row.title": "Дважды щелкните, чтобы переместить RX сюда",
  "js8.panel.offsets.dt.title": "DT — дельта времени отправителя относительно слотового часов, в миллисекундах. Отрицательное значение означает, что сообщение раннее.",
  "js8.header.power.label": "Водить",
  "js8.header.power.title": "Аудио привод TX — установите так, чтобы ALC установки едва двигался; JS8 — это режим с постоянной огибающей, но перегруженная звуковая карта всё равно брызгает",
  "js8.header.speed.title": "JS8 — JS8Call-совместимый режим клавиатуры на волновой форме FT8",
