  "sstv.refuse.heic": "Фотографии iPhone в формате HEIC здесь не читаются — Nexus не имеет декодера HEVC. На iPhone: Настройки → Камера → Форматы → Наиболее совместимый (новые фотографии будут JPEG), или Настройки → Фото → Перенос на Mac или ПК → Автоматически (конвертирует при отправке). Затем повторно отправьте эту фотографию.",
  "sstv.refuse.avif": "Это файл AVIF. SSTV отправляет JPEG, PNG, WebP, BMP или GIF — экспортируйте или сохраните как один из них.",
