  "sstv.rx.nocapture": "Слушаю, но никакой аудиосигнал не поступает на декодер — устройство захвата ничего не передает. Проверьте, что входное устройство (RX) — это радио; слышать сигнал через динамик не значит, что приложение захватывает его.",
  "sstv.rx.starting": "Приёмник запущен — звук ещё не поступал на декодер.{{where}}",
  "sstv.rx.unsupported": "Слышал заголовок SSTV {{age}} назад в режиме, который эта сборка не может декодировать{{vis}}. Сигнал и аудиопуть в порядке — изображения Scottie, Martin, Robot и PD все декодируются.",
  "sstv.rx.decoded": { "one": "Изображение {{count}} декодировано с момента вооружения, последнее было {{age}} назад. Ожидание следующего заголовка.", "other": "С момента взведения расшифровано {{count}} изображений, последнее {{age}} назад. Ожидание следующего заголовка." },
  "sstv.rx.silent": "Аудио поступает, но оно тихое. Если вы слышите сигнал через динамик, приложение использует другой вход — проверьте устройство ввода (RX) и усиление (RX), если уровень просто низкий.{{where}}",
  "sstv.rx.listening": "Прослушивание аудио, заголовка SSTV пока нет — изображение декодируется автоматически, когда начинается воспроизведение.{{where}}",
  "sstv.rx.unreachable": "Невозможно прочитать состояние приёмника — приложение не отвечает. Декодер может быть всё ещё запущен.",
  "sstv.dataMode.drops": "Между кадрами это радио возвращается в обычный USB, и его фильтры режима данных идут вместе с ним.",
