  "phone.tx.turnedBackOn": "TX был выключен — включил его снова. Нажмите PTT ещё раз, чтобы говорить.",
  "phone.tx.remoteLock": "Lock (с гарнитурой без рук PTT) не работает через Remote. Снимите отметку с Lock, затем удерживайте PTT или пробел, чтобы говорить.",
  "phone.tx.clockRepair": "Не активировано: идет ремонт часов, и ничего не начинает передаваться, пока он не завершится (максимум две минуты).",
  "phone.scope.tuneHint": "Прокрутите здесь, чтобы настроить VFO",
  "phone.scope.yaesu.aria": "Панадаптер",
