  "phone.scope.yaesu.span.title": "Ширина охвата на РАДИО — приложение отображает то, что оно сообщает обратно",
  "phone.scope.yaesu.pos.aria": "Положение панадаптера (устанавливает радио)",
  "phone.scope.yaesu.pos.title": "Где находится сканирование. FIX выводится от края полосы — протокол CAT не сообщает собственное FIX окно радио, поэтому сверяйте его с шкалой устройства.",
  "phone.scope.yaesu.pos.center": "Центр",
