  "phone.scope.yaesu.pos.fix": "Исправить",
  "phone.scope.nativeRf.label": "RF Панадаптер",
  "phone.scope.nativeRf.title": "Родной панадаптер RF — это настоящий спектр RF вокруг вашего циферблата, а не демодулированная полоса пропускания аудио.",
  "phone.scope.audio.label": "Полоса пропускания",
  "phone.scope.audio.title": "Приёмник AUDIO спектра на оси вашей установки: центральная линия — это ваш циферблат, а полоса пропускания находится на той стороне, на которой находится ваша боковая полоса (USB сверху, LSB снизу) — другая половина тиха, потому что SSB приёмник слышит только одну сторону. Это не панадаптер для всей полосы RF, поэтому голос заполняет полосу пропускания, а не скользит по ней при настройке.",
  "phone.scope.audio.sub": "RX аудио",
