  "phone.keyer.txOff": "TX выключен — нажмите PTT один раз, чтобы включить его снова, затем воспроизведите сообщение",
  "phone.keyer.radioHasMic": "Голосовой упорядочитель не может воспроизводить звук, пока радио держит микрофон: с включённым нативным аудио Flex DAX, телефон в шеке использует собственный микрофон радио, поэтому записанное сообщение не будет отправлено. Ничего не было активировано.",
