  "remote.stations": "Ваши станции",
  "remote.pilotIntro": "Управляйте своей станцией через одобренный браузер. Компьютер в шеке поддерживает радио и остается под контролем: то, что вы нажимаете и вводите здесь, отправляется на станцию, а эта страница показывает, что станция сообщает в ответ.",
  "remote.signedOutPitch": "Управляйте своей станцией с любого одобренного вами браузера, пока радио остаётся в стойле.",
  "remote.signIn": "Войти",
  "remote.createAccount": "Создать аккаунт",
  "remote.signUpHint": "Новый здесь? Создайте аккаунт, затем введите шестизначный код, который мы отправим вам по электронной почте. После этого вы будете авторизованы.",
  "remote.supportDetails": "Детали поддержки",
  "remote.signOut": "Выйти",
  "remote.notConfigured": "Удалённая служба ещё не настроена.",
  "remote.applicationLoggingPreview": "Дисплей станции с возможностью ручного ведения журнала. Управление радиостанцией и передачей остаётся недоступным.",
  "remote.loggingLocalHint": "Одобрение браузера также позволяет ему вести журнал контактов. Чтобы ограничить браузер, отозвайте разрешение на ведение журнала здесь. Ведение журнала никогда не предоставляет управление радио или передачей.",
  "remote.loggingTakeOver": "Прекратить удалённое ведение журнала и очистить разрешения",
  "remote.controlRequestFailed": "Команда не была подтверждена. Проверьте разрешение на управление станцией и текущие показания.",
  "remote.controlNotSent": "Не отправлено. Ничего не дошло до станции, поэтому там ничего не изменилось. Попробуйте снова.",
  "remote.controlBusy": "Станция была занята, и ничего не изменилось. Попробуйте снова.",
  "remote.controlLocalHint": "Одобрение браузера даёт ему управление станцией: поддержка приёмника, управление радио и усилителем, а также Stop TX, который останавливает любую передачу на станции. При включённом стриминге они также позволяют ему транслировать это окно и использовать Nexus так, как вы здесь, включая передачу. Чтобы ограничить браузер, отзовите его здесь, что также завершит его трансляцию.",
  "remote.b1.outsidePrivileges": "Не изменено. Эта частота передачи находится за пределами ваших лицензийных полномочий.",
  "remote.b1.workUnavailable": "Эту точку нельзя использовать из браузера. На станции ничего не изменилось.",
  "remote.b1.rotatorNoHeading": "Нет заголовка от станции — ничего не настроено, или управление ротатором не отвечает.",
  "remote.b1.rotatorPointing": "Направление ротатора на {{call}}.",
  "remote.transmitAllow": "Разрешить передачу FT8/FT4 с удаленной страницы",
  "remote.transmitRevoke": "Отозвать передачу FT8/FT4 с удалённой страницы",
  "remote.transmitLocalHint": "FT8/FT4 передача с удаленной страницы также требует управления станцией. После того как разрешено, это разрешение сохраняется при перезагрузках, пока вы не отзовете его здесь, а отозвав его, передача FT8/FT4 данного браузера с этой страницы прекращается сразу. С страницы ничего не передается, пока браузер не нажмет TX On. Потоковый браузер в этом не нуждается: через поток он передает так, как вы бы делали это здесь.",
