  "remote.stream.mic.level.title": "Насколько громко ваш голос доходит до станции, относительно уровня вашего микрофона. Говорите так, как вы бы говорили в эфире, и увеличивайте громкость, пока ваши самые громкие слова не достигнут конца шкалы. Пики удерживаются на 3 dB ниже полного масштаба, поэтому клиппинга не происходит. Этот браузер запоминает это.",
  "remote.stream.mic.meter": "Уровень микрофона отправлен",
