  "remote.stream.mic.denied.site": "Микрофон заблокирован для этого сайта. Разрешите его в настройках браузера для этого сайта (иконка слева от адресной строки), затем снова включите микрофон.",
  "remote.stream.mic.denied.system": "Настройки конфиденциальности вашего компьютера блокируют доступ к микрофону для браузера. На Windows откройте Настройки ▸ Конфиденциальность и безопасность ▸ Микрофон и включите доступ к микрофону, включая приложения для рабочего стола. На Mac откройте Системные настройки ▸ Конфиденциальность и безопасность ▸ Микрофон, включите браузер и откройте его заново. Затем снова включите микрофон.",
  "remote.stream.mic.denied.dismissed": "Вопрос браузера о микрофоне был закрыт без ответа. Включите микрофон снова и выберите Разрешить.",
