  "remote.stream.mic.denied.busy": "Микрофон был найден, но не может запуститься. Возможно, его использует другая программа: закройте эту программу, затем снова включите микрофон.",
  "remote.stream.mic.denied.other": "Браузер не смог получить доступ к микрофону ({{name}}). Проверьте настройки браузера для этого сайта и настройки микрофона на компьютере, затем снова включите микрофон.",
