  "remote.nativeAwaitingConfirmation": "Сначала подтвердите эту станцию в вашем браузере — на странице Remote спрашивается, прикреплять её или нет. Затем снова подтвердите здесь.",
  "remote.nativeStationKeyPinned": "Сервис Remote использует другой ключ для этой станции, чем тот, которым он подписывает свой поток, поэтому браузеры отказываются воспроизводить его поток. Используйте функцию Отозвать доступ к станции, затем снова подключите эту станцию.",
  "remote.vaultFailed": "Разблокируйте хранилище учетных данных вашей операционной системы и попробуйте снова. Удаленный доступ остается отключенным, если его учетные данные не могут быть безопасно сохранены.",
  "remote.nativeRevoked": "Доступ к этой станции был отозван из браузера, поэтому она перестала подключаться. Здесь ничего не сломано — снова подключите её ниже, когда захотите вернуть.",
  "remote.nativeTrialEnded": "Ваш пробный период Remote закончился, поэтому эту станцию не удалось добавить к аккаунту. Ваше радио, ваш журнал и ваши настройки остались без изменений.",
  "remote.nativeTrialDisabled": "Удалённый доступ для этой учётной записи был отключён, поэтому эту станцию невозможно было добавить к ней. Это не связано с окончанием пробного периода. Ваше радио, ваш журнал и ваши настройки не затронуты.",
  "remote.stationName": "Название станции",
  "remote.renameStation": "Переименовать",
  "remote.saveName": "Сохранить имя",
  "remote.cancelRename": "Отмена",
  "remote.openService": "Войдите в сервис:",
  "remote.codeExpires": "Этот код истекает через десять минут.",
  "remote.approvePairing": "Одобрить это сопоставление аккаунтов",
  "remote.cancelPairing": "Отменить сопряжение",
  "remote.restartHint": "Удалённый доступ остаётся включённым при перезапуске Nexus: если он был включён при закрытии Nexus, он включается снова и восстанавливает соединение. Одобренные браузеры сохраняют то, что вы разрешили, включая передачу FT8/FT4. Передача всегда выключена после перезапуска, пока браузер снова не включит её. Выключение удалённого доступа только разрывает соединение: повторное включение восстанавливает настройки каждого одобренного браузера.",
  "remote.disable": "Выключить пульт",
  "remote.enable": "Включить пульт",
  "remote.autostartOffer": "Пульт сможет вернуться только после перезагрузки этого компьютера, если Nexus тоже запустится. Запустить Nexus при входе в этот компьютер?",
  "remote.autostartOfferAccept": "Запускать Nexus при входе в систему",
