  "remote.browserKeyNotPinned": "Этот браузер не может воспроизводить поток, пока вы снова не утвердите его здесь. Сначала проверьте, что этот ключ совпадает с тем, который показывает браузер.",
  "remote.native.browsers": "Ваши браузеры",
