  "remote.native.remove": "Удалить",
  "remote.native.advanced": "продвинутый",
  "remote.approve": "Одобрить",
  "remote.approval.title": "Разрешить {{browser}} транслировать эту станцию?",
  "remote.approval.body": "Браузер, вошедший в ваш аккаунт Remote, запрашивает потоковую трансляцию этой станции и управление ею так же, как вы делали бы здесь, включая передачу. Одобряйте это только если этот ключ соответствует ключу, который показывает браузер: {{key}}.",
  "remote.approval.bodyAgain": "Этот браузер был одобрен ранее, но он не может транслировать, пока вы снова не одобрите его здесь. Когда он транслирует, он может управлять этой станцией так же, как и вы здесь, включая передачу. Одобряйте его только если этот ключ совпадает с тем, что показывает браузер: {{key}}.",
  "remote.approval.deny": "Отказать",
  "remote.lan.switch": "Remote через эту сеть",
  "remote.lan.intro": "Давайте Nexus на другом компьютере в этой сети для работы с этой станцией, интернет не нужен. Свяжите каждый компьютер здесь один раз; доступ сохраняется до его удаления.",
  "remote.lan.off": "Выкл.",
  "remote.lan.starting": "Запуск…",
  "remote.lan.listening": "Прослушивание на {{address}}. Только подключенные здесь компьютеры могут соединяться.",
  "remote.lan.reason.noKey": "Выкл.: эта станция не имеет сетевого ключа, который она могла бы прочитать. Нажмите Сбросить сетевую идентичность в разделе Сетевая идентичность ниже, затем снова включите это. Сброс удаляет все сопряжённые компьютеры, поэтому каждый из них придётся сопрягать заново.",
  "remote.lan.reason.endedAtShack": "Выкл.: дистанционное управление здесь завершено. Включите это снова, когда захотите.",
  "remote.lan.reason.addressGone": "Не прослушивается: {{address}} не является адресом этого компьютера в данный момент. Nexus будет снова прослушивать его, когда вернется, или выберите другую сеть.",
  "remote.lan.reason.chooseAddress": "Не прослушивается: выберите, на каких сетях этого компьютера слушать.",
