  "remote.lan.noComputers": "Компьютер ещё не подключён.",
  "remote.lan.atShackOnly": "Только на самой станции: это нельзя сделать через поток.",
  "remote.lan.full": "Восемь компьютеров уже соединены парами. Удалите один, чтобы соединить другой.",
  "remote.lan.vaultFailed": "Nexus не может прочитать или сохранить сетевой ключ этой станции и сопряженные компьютеры в хранилище учетных данных вашей операционной системы. Нажмите Сбросить идентификатор сети в разделе Идентификатор сети ниже. Сброс удаляет каждый сопряженный компьютер, поэтому каждый из них придется сопрягать снова.",
  "remote.lan.failed": "Nexus не смог это сделать. Попробуйте снова.",
  "remote.lan.resetTitle": "Сетевая идентичность",
  "remote.lan.resetHint": "Сброс создаёт новый сетевой ключ и удаляет все сопряжённые компьютеры. Используйте его, если ключ этого компьютера мог быть скопирован, а затем снова сопрягайте ваши компьютеры.",
  "remote.lan.reset": "Сбросить идентификатор сети",
  "remote.lan.unavailable": "Этой станции и другому компьютеру пока что нужен Windows.",
  "remote.lan.firewallFirst": "В первый раз при включении Windows спрашивает, может ли Nexus использовать сети. Разрешить только частные сети.",
