  "remote.lan.networkHint": "Виртуальные адаптеры и VPN не предоставляются: другие компьютеры в этой сети не могут получить доступ к этому через них.",
  "remote.lan.notNamed": "Windows не позволит другим компьютерам найти эту станцию по имени, поэтому введите её адрес на другом компьютере.",
  "remote.lan.guest": "Гостевая сеть, или та, которая держит свои устройства отдельно, предотвращает доступ других компьютеров к этому, и Nexus не может определить это отсюда.",
  "remote.lan.firewall.ask": "Когда Windows спрашивает, может ли Nexus использовать эту сеть, разрешайте только частные сети.",
  "remote.lan.firewall.public": "Windows называет эту сеть «Общедоступной», поэтому её брандмауэр не пускает другие компьютеры. Если это ваша собственная сеть, сделайте её «Частной» в Windows Настройки ▸ Сеть и Интернет.",
  "remote.lan.firewall.blocked": "Брандмауэр Windows блокирует Nexus в этой сети, как это происходит после отмены его запроса. Разрешите Nexus в частных сетях в Windows Безопасность ▸ Брандмауэр и защита сети ▸ Разрешить приложение через брандмауэр.",
  "remote.lan.firewall.blocksAll": "Брандмауэр Windows блокирует все входящие соединения в этой сети, поэтому ни один другой компьютер не может получить доступ к этой станции.",
  "remote.lan.firewall.managed": "Брандмауэр этого компьютера настроен политикой администратора, которая может не пускать другие компьютеры. Попросите того, кто им управляет, разрешить Nexus.",
  "remote.lan.firewall.silent": "Брандмауэр блокирует новые программы в этой сети без запроса. Разрешите Nexus в частных сетях в Windows Безопасность ▸ Брандмауэр и защита сети ▸ Разрешить приложение через брандмауэр.",
  "remote.lan.reach.otherNetwork": "Этот адрес не находится в сети этого компьютера. Подключитесь к сети станции или проверьте адрес, который показывает станция.",
  "remote.lan.reach.refused": "Компьютер станции ответил, но на этом порту никто не слушает: Remote в этой сети выключен или находится на другом порту. Проверьте адрес, который показывает станция.",
  "remote.lan.reach.noAnswer": "Нет ответа от станции. Remote через эту сеть может быть выключен там, его брандмауэр может блокировать Nexus (разрешите это в частных сетях на станции), сеть может изолировать свои устройства друг от друга (гостевой Wi-Fi часто так делает), или станция может быть в спящем режиме. Nexus не может сказать, что именно здесь.",
  "remote.lan.find.unavailable": "Поиск станций по имени на этом компьютере не работает. Введите адрес, который показывает станция.",
