  "settings.confirmations.cloudlog.stations.title": "Спросите у собственного Cloudlog/Wavelog, какие у него есть расположения станций, и заполните номер. Это отправляет ваш API-ключ на ваш экземпляр, и только когда вы нажмете это.",
  "settings.confirmations.cloudlog.stations.none": "Этот экземпляр не сообщает о местоположениях станций — сначала добавьте одну в Cloudlog/Wavelog.",
  "settings.confirmations.cloudlog.stations.callMismatch": "Позывной этого места - {{location}}, но Nexus регистрируется как {{call}}: Wavelog откажется от этих QSOs. Выберите место с вашим позывным или измените этот в Wavelog.",
  "settings.confirmations.cloudlog.stations.gridMismatch": "Сетка этого места — {{location}}, а ваша сетка — {{grid}}: Wavelog помещает эти QSOs под {{location}} и отклоняет любые, которые имеют вашу сетку. Выберите место с вашей сеткой или измените это в Wavelog.",
  "settings.confirmations.cloudlog.apiKey.label": "API ключ",
