  "settings.rigControl.ratedWatts.hint": "То, что этот радиоприемник выдает на полной мощности. Он устанавливает верхнюю границу шкалы индикатора мощности передачи, поэтому установленный QRP показывает весь диапазон шкалы, а не останавливается на первой отметке. Это рейтинг радиоприемника, а не ваш предел мощности.",
